sysauto_script.script:
// Find overdue NeedIt Tasks and fire an event per record
(function() {
  var nowGdt = new GlideDateTime();

  var gr = new GlideRecord('x_58872_needit_needit_task');
  gr.addNotNullQuery('due_date');
  gr.addQuery('due_date', '<=', nowGdt.getValue());

  // Prefer explicit non-closed states, or confirm the exact value for "Closed Complete"
  // Example keeps only Open & WIP (adjust for your choices):
  // gr.addQuery('state', 'IN', '0,1');
  gr.addQuery('state', '!=', 3); // <-- confirm 3 is Closed Complete in your instance

  gr.query();

  while (gr.next()) {
    gs.info('Overdue NeedIt Task = ' + gr.getDisplayValue('number'));
    gs.eventQueue('x_58872_needit.overdueNeedItTask', gr, gr.getValue('number'), gs.getUserName());
  }
})();
